CREATE OR REPLACE FUNCTION public.instructor_uploaded_material(_course uuid,_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.instructor_course_access(_course) AND split_part(_path,'/',1)=_course::text AND split_part(_path,'/',2)=auth.uid()::text AND EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='training-materials' AND name=_path) $$; REVOKE ALL ON FUNCTION public.instructor_uploaded_material(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.instructor_uploaded_material(uuid,text) TO authenticated; ALTER POLICY material_create ON public.course_materials WITH CHECK(created_by=auth.uid() AND public.instructor_uploaded_material(course_id,file_path));